(function(){const status=document.getElementById('status');document.getElementById('check').addEventListener('click',function(){status.textContent='Checking signed releases…';if(window.VyomBridge&&typeof window.VyomBridge.checkForUpdates==='function'){window.VyomBridge.checkForUpdates()}else{status.textContent='Native update bridge unavailable'}});document.getElementById('apply').addEventListener('click',function(){const prompt=document.getElementById('prompt').value.trim();if(!prompt){status.textContent='Describe the UI change first';return}status.textContent='Preparing a minimal UI patch…';if(window.VyomBridge&&typeof window.VyomBridge.applyUiPrompt==='function'){window.VyomBridge.applyUiPrompt(prompt)}else{status.textContent='Native UI editor unavailable'}});document.getElementById('selfchange').addEventListener('click',function(){if(window.VyomBridge&&typeof window.VyomBridge.openSelfChange==='function'){window.VyomBridge.openSelfChange()}else{status.textContent='Native self-change bridge unavailable'}});if(window.VyomBridge&&typeof window.VyomBridge.bundleVersion==='function'){document.getElementById('version').textContent='Bundle v'+window.VyomBridge.bundleVersion()}})();